#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include "buffer.h"
#include "helpers.h"

void unit_test_buffer_new_with_string_length_valid_string_and_length(void) {
    // Setup: create a valid string and length
    char *test_str = strdup("hello world");
    size_t test_len = 5; // Only use "hello"

    // Test: call buffer_new_with_string_length
    buffer_t *buf = buffer_new_with_string_length(test_str, test_len);

    // Assertions
    assert(buf != NULL);
    assert(buf->len == test_len);
    assert(buf->data == test_str);
    assert(buf->alloc == test_str);

    // The buffer does not copy the string, so the content should match the first 'len' bytes
    // We can check that the first 'len' bytes of buf->data match the original string
    assert(strncmp(buf->data, "hello", test_len) == 0);

    // Cleanup
    buffer_free(buf);
    // free(test_str); // Removed to avoid double free
}

